# Verify L(K_7) properties more carefully

import itertools

# Build graph
n = 7
subsets = list(itertools.combinations(range(n), 2))
# 21 vertices
label = {s: i for i, s in enumerate(subsets)}

edges = []
for i, s in enumerate(subsets):
    for j, t in enumerate(subsets):
        if i < j and (s[0] in t or s[1] in t):
            edges.append((i, j))

# Build adjacency
adj = {i: set() for i in range(21)}
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

# 1. Verify maximum independent set size is at most 4
# We know alpha(L(K_n)) = floor(n/2) = 3 for n=7
# But let's verify via brute force for size 4
def is_independent(vs):
    for i in range(len(vs)):
        for j in range(i+1, len(vs)):
            if vs[j] in adj[vs[i]]:
                return False
    return True

found_4 = None
for combo in itertools.combinations(range(21), 4):
    if is_independent(combo):
        found_4 = combo
        break
print(f"Independent set of size 4 found: {found_4}")

# 2. Verify vertex connectivity >= 4
# For a regular graph, we can check that after removing any 3 vertices, the graph remains connected
import random

def is_connected(removed_set):
    # BFS from a remaining vertex
    start = None
    for v in range(21):
        if v not in removed_set:
            start = v
            break
    if start is None:
        return False  # all vertices removed
    visited = {start}
    stack = [start]
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if v not in removed_set and v not in visited:
                visited.add(v)
                stack.append(v)
    return len(visited) == 21 - len(removed_set)

# Check all subsets of size 3
connectivity_ok = True
for removed in itertools.combinations(range(21), 3):
    if not is_connected(set(removed)):
        connectivity_ok = False
        print(f"Disconnected when removing: {removed}")
        break
print(f"Connected after removing any 3 vertices: {connectivity_ok}")

# Actually L(K_n) has connectivity 2n-4 = 10, so it's definitely >= 4
print(f"Vertex connectivity of L(K_7) = {2*7-4}")

